CREATE OR REPLACE FUNCTION public.rpc_rank_drop(p_world uuid, p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); d deed; r deed_rank_def; v_n int;
begin
